def dt_format_to_regex(format):
    """Convert a C standard datetime format string to a regex pattern.

    This function maps common strftime/strptime format codes to their
    corresponding regex patterns for parsing datetime strings.

    Supported format codes:
        %Y - Year with century (e.g., 2023) -> \d{4}
        %y - Year without century (e.g., 23) -> \d{2}
        %m - Month as zero-padded decimal (01-12) -> \d{1,2}
        %d - Day of month as zero-padded decimal (01-31) -> \d{1,2}
        %H - Hour (24-hour) as zero-padded decimal (00-23) -> \d{1,2}
        %I - Hour (12-hour) as zero-padded decimal (01-12) -> \d{1,2}
        %M - Minute as zero-padded decimal (00-59) -> \d{1,2}
        %S - Second as zero-padded decimal (00-59) -> \d{1,2}
        %f - Microsecond as decimal number (000000-999999) -> \d+
        %z - UTC offset (+HHMM or -HHMM) -> [-+]\d{4}
        %Z - Timezone name -> [A-Za-z]+
        %c - Locale's appropriate date and time representation
        %x - Locale's appropriate date representation
        %X - Locale's appropriate time representation
        %% - Literal '%' character -> %
        Any other text is escaped for regex safety

    :param format: A C standard datetime format string
    :return: A regex pattern string
    """
    result = []
    i = 0
    while i < len(format):
        if format[i] == '%':
            if i + 1 >= len(format):
                result.append('%')
                break
            next_char = format[i + 1]
            if next_char == '%':
                result.append(r'\%')
                i += 2
            elif next_char == 'Y':
                result.append(r'\d{4}')
                i += 2
            elif next_char == 'y':
                result.append(r'\d{2}')
                i += 2
            elif next_char == 'm':
                result.append(r'\d{1,2}')
                i += 2
            elif next_char == 'd':
                result.append(r'\d{1,2}')
                i += 2
            elif next_char == 'H':
                result.append(r'\d{1,2}')
                i += 2
            elif next_char == 'I':
                result.append(r'\d{1,2}')
                i += 2
            elif next_char == 'M':
                result.append(r'\d{1,2}')
                i += 2
            elif next_char == 'S':
                result.append(r'\d{1,2}')
                i += 2
            elif next_char == 'f':
                result.append(r'\d+')
                i += 2
            elif next_char == 'z':
                # Flexible timezone: ±HHMM or ±HH:MM or ±HHMMSS or ±HH:MM:SS
                result.append(r'(?:[-+]\d{2}:?\d{2}(?::\d{2})?)')
                i += 2
            elif next_char == 'Z':
                result.append(r'[A-Za-z]+')
                i += 2
            elif next_char == 'c':
                # Locale's appropriate date and time representation
                result.append(
                    r'(\d{1,2}\s+[A-Za-z]+\s+\d{1,2}\s+\d{1,2}:\d{1,2}:\d{1,2}(\.\d+)?)'
                )
                i += 2
            elif next_char == 'x':
                # Locale's appropriate date representation
                result.append(r'(\d{1,2}[-/]\d{1,2}[-/]\d{2,4})')
                i += 2
            elif next_char == 'X':
                # Locale's appropriate time representation
                result.append(r'(\d{1,2}:\d{1,2}(:\d{1,2}(\.\d+)?)?)')
                i += 2
            else:
                # Unknown format code, keep as literal
                result.append(re.escape('%' + next_char))
                i += 2
        else:
            # Regular character - escape for regex
            result.append(re.escape(format[i]))
            i += 1

    return ''.join(result)
